                verticalAlignment = Alignment.CenterVertically
            ) {
                // Home
                NavBarItem(
                    icon = Icons.Default.Home,
                    isSelected = currentRoute == "home",
                    onClick = { onNavigate("home") }
                )

                // Favorites
                NavBarItem(
                    icon = if (currentRoute == "favorites")
                        Icons.Default.Favorite
                    else
                        Icons.Default.FavoriteBorder,
                    isSelected = currentRoute == "favorites",
                    onClick = { onNavigate("favorites") }
                )

                // Reserve space for center floating button
                Spacer(modifier = Modifier.size(60.dp))

                // History
                NavBarItem(
                    icon = Icons.Default.History,
                    isSelected = currentRoute == "result",
                    onClick = { onNavigate("result") }
                )

                // Profile
                NavBarItem(
                    icon = Icons.Default.Person,
                    isSelected = currentRoute == "profile",
                    onClick = { onNavigate("profile") }
                )

                // Spacer
                Box(modifier = Modifier.size(60.dp))
            }
        }

        //  Enhanced Floating Center Button - Placed separately to avoid clipping by the bar's shadow/background
        Box(
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(bottom = 20.dp)
                .size(70.dp)
                .clip(CircleShape)
                .background(
                    brush = androidx.compose.ui.graphics.Brush.linearGradient(
                        colors = listOf(GradientStart, com.sanskar.listenx.ui.theme.GradientEnd)
                    )
                ),
            contentAlignment = Alignment.Center
        ) {
            IconButton(onClick = { onNavigate("listening") }) {
                Icon(
                    Icons.Default.Mic,
                    contentDescription = "Listen",
                    tint = Color.White,
                    modifier = Modifier.size(28.dp)
                )
            }
        }
    }
}

@Composable
fun NavBarItem(
    icon: ImageVector,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    val tint by animateColorAsState(
        targetValue = if (isSelected) GradientStart else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f),
        animationSpec = spring(), label = "tint"
    )

    val scale by animateFloatAsState(
        targetValue = if (isSelected) 1.2f else 1.0f,
        animationSpec = spring(), label = "scale"
    )

    Column(
        modifier = Modifier
            .size(56.dp)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null,
                onClick = onClick
            ),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Icon(
            imageVector = icon,
            contentDescription = null,
            tint = tint,
            modifier = Modifier
                .size(26.dp)
                .graphicsLayer(scaleX = scale, scaleY = scale)
        )

        if (isSelected) {
            Box(
                modifier = Modifier
                    .padding(top = 4.dp)
                    .size(4.dp)
                    .background(GradientStart, CircleShape)
            )
        }
    }
}

