package com.sanskar.listenx.data.repository

import android.util.Log
import com.google.gson.Gson
import com.sanskar.listenx.data.api.RetrofitClient
import com.sanskar.listenx.data.model.FingerprintRequest
import com.sanskar.listenx.data.model.SongRecognitionResponse

/**
 * Repository for song recognition - handles all API calls
 * Following Repository pattern from MVVM
 */
class SongRecognitionRepository {
    private val api = RetrofitClient.getApi()
    private val gson = Gson()
    private val TAG = "SongRecognitionRepo"

    /**
     * Send audio fingerprint to backend for song matching
     *
     * @param fingerprint Map of hash -> timestamp pairs
     * @return List of matched songs
     */
    suspend fun matchFingerprint(fingerprint: Map<Int, Int>): List<SongRecognitionResponse> {
        return try {
            val hexFingerprint = fingerprint.mapKeys { (hash, _) -> hash.toUInt().toString(16) }
            val request = FingerprintRequest(hexFingerprint)

            // Log the JSON payload (Option 1)
            val jsonPayload = gson.toJson(request)
            Log.d(TAG, "Request JSON: $jsonPayload")

            api.matchFingerprint(request)
        } catch (e: Exception) {
            Log.e(TAG, "Error matching fingerprint: ${e.message}")
            throw Exception("Failed to match fingerprint: ${e.message}")
        }
    }

    /**
     * Get total number of songs in the database
     */
    suspend fun getTotalSongs(): Int {
        return try {
            val response = api.getTotalSongs()
            response["total"] ?: response["count"] ?: 0
        } catch (e: Exception) {
            Log.e(TAG, "Error getting total songs: ${e.message}")
            0
        }
    }
}

package com.sanskar.listenx.data.repository

import android.util.Log
import com.google.gson.Gson
import com.sanskar.listenx.data.api.RetrofitClient
import com.sanskar.listenx.data.model.FingerprintRequest
import com.sanskar.listenx.data.model.SongRecognitionResponse
import retrofit2.HttpException

/**
 * Repository for song recognition - handles all API calls
 * Following Repository pattern from MVVM
 */
class SongRecognitionRepository {
    private val api = RetrofitClient.getApi()
    private val gson = Gson()
    private val TAG = "SongRecognitionRepo"

    /**
     * Send audio fingerprint to backend for song matching
     *
     * @param fingerprint Map of hash -> timestamp pairs
     * @return List of matched songs
     */
    suspend fun matchFingerprint(fingerprint: Map<Int, Int>): List<SongRecognitionResponse> {
        return try {
            val hexFingerprint = fingerprint.mapKeys { (hash, _) -> hash.toUInt().toString(16) }
            val request = FingerprintRequest(hexFingerprint)

            // Log the JSON payload for debugging
            val jsonPayload = gson.toJson(request)
            Log.d(TAG, "Request JSON: $jsonPayload")
            Log.d(TAG, "Fingerprint hashes count: ${hexFingerprint.size}")

            api.matchFingerprint(request)
        } catch (e: HttpException) {
            // Log detailed HTTP error information
            val errorBody = try {
                e.response()?.errorBody()?.string() ?: "No error body"
            } catch (ex: Exception) {
                "Could not read error body: ${ex.message}"
            }
            Log.e(TAG, "HTTP Error ${e.code()}: ${e.message()}")
            Log.e(TAG, "Error Body: $errorBody")
            throw Exception("Backend error ${e.code()}: ${e.message()}. Body: $errorBody")
        } catch (e: Exception) {
            Log.e(TAG, "Error matching fingerprint: ${e.message}", e)
            throw Exception("Failed to match fingerprint: ${e.message}")
        }
    }

    /**
     * Get total number of songs in the database
     */
    suspend fun getTotalSongs(): Int {
        return try {
            val response = api.getTotalSongs()
            response["total"] ?: response["count"] ?: 0
        } catch (e: Exception) {
            Log.e(TAG, "Error getting total songs: ${e.message}")
            0
        }
    }
}

